import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { Observable, map, catchError, of } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { NotificationService } from '../../../core/services/notification/notification.service';

export interface PersonaDisponible {
  persona_id: number;
  nombre_completo: string;
  nombres: string;
  apellidos: string;
  numero_documento: string;
  tipo_documento?: string;
  foto_cifrada?: string;
}


@Injectable({
  providedIn: 'root'
})
export class PersonalSyncService {
  private apiUrl = `${environment.apiUrl}/personal`;

  constructor(
    private http: HttpClient,
    private notificationService: NotificationService
  ) {}

  /**
   * Buscar personas disponibles para crear personal
   * GET /api/v1/personal/personas-disponibles
   */
  buscarPersonasDisponibles(termino: string = ''): Observable<PersonaDisponible[]> {
    let params = new HttpParams();
    if (termino && termino.length >= 2) {
      params = params.set('q', termino);
    }

    return this.http.get<any>(`${this.apiUrl}/personas-disponibles`, { params }).pipe(
      map(response => {
        console.log('📥 Personas disponibles:', response);
        if (response.success) {
          return response.data || [];
        }
        return [];
      }),
      catchError(error => {
        console.error('❌ Error buscando personas disponibles:', error);
        this.notificationService.showError('Error al buscar personas disponibles');
        return of([]);
      })
    );
  }

  /**
   * Verificar disponibilidad de una persona específica
   * GET /api/v1/personal/verificar-disponibilidad/{personaId}
   */
  verificarDisponibilidad(personaId: number): Observable<any> {
    return this.http.get<any>(`${this.apiUrl}/verificar-disponibilidad/${personaId}`).pipe(
      map(response => response.data || { disponible: false }),
      catchError(error => {
        console.error('❌ Error verificando disponibilidad:', error);
        return of({ disponible: false, razon: 'Error en la verificación' });
      })
    );
  }

  /**
   * Obtener estadísticas de personal
   * GET /api/v1/personal/estadisticas
   */
  getEstadisticas(): Observable<any> {
    return this.http.get<any>(`${this.apiUrl}/estadisticas`).pipe(
      map(response => response.data || {}),
      catchError(error => {
        console.error('❌ Error obteniendo estadísticas:', error);
        return of({});
      })
    );
  }

  /**
   * Búsqueda avanzada
   * GET /api/v1/personal/buscar
   */
  buscarAvanzado(params: any): Observable<any> {
    let httpParams = new HttpParams();
    Object.keys(params).forEach(key => {
      if (params[key] !== null && params[key] !== undefined && params[key] !== '') {
        httpParams = httpParams.set(key, params[key].toString());
      }
    });

    return this.http.get<any>(`${this.apiUrl}/buscar`, { params: httpParams }).pipe(
      map(response => response),
      catchError(error => {
        console.error('❌ Error en búsqueda avanzada:', error);
        return of({ data: [], meta: { total: 0 } });
      })
    );
  }

  /**
   * Validar datos antes de crear personal
   */
  validarDatosCreacion(data: any): string[] {
    const errores: string[] = [];

    if (!data.persona_id) {
      errores.push('Debe seleccionar una persona');
    }

    if (!data.cargo_id) {
      errores.push('Debe seleccionar un cargo');
    }

    if (!data.fecha_ingreso) {
      errores.push('La fecha de ingreso es requerida');
    }

    // Validar que la fecha de egreso no sea anterior a la de ingreso
    if (data.fecha_ingreso && data.fecha_egreso) {
      const ingreso = new Date(data.fecha_ingreso);
      const egreso = new Date(data.fecha_egreso);
      if (egreso < ingreso) {
        errores.push('La fecha de egreso no puede ser anterior a la fecha de ingreso');
      }
    }

    return errores;
  }
}
